// === Tab: mySketch ===
// x, y, vx, vy, c, dispersed?
const num = 1000
const ax = new Float32Array(num)
const ay = new Float32Array(num)
const avx = new Float32Array(num)
const avy = new Float32Array(num)
const ac = new Uint8Array(num * 3)
const ad = new Uint8Array(num)

const dispersionX = 100
const dispersionWidth = 100

function drawLines() {
	stroke(255)
	strokeWeight(5)
	line(dispersionX, 0, dispersionX, height)
	line(dispersionX + dispersionWidth, 0, dispersionX + dispersionWidth, height)

	strokeWeight(1)
}

function setup() {
	createCanvas(640, 300)
	background(30)

	colorMode(HSB)
	for (let i = 0; i < num; i++) {
		ax[i] = 0
		ay[i] = height/2 + random(-1, 1)
		avx[i] = 1
		avy[i] = 0
		ad[i] = 0

		// random color that doesn't mix red and blue
		let hue = parseInt(random(0, 240))
		let c = color(hue, 100, 100)

		ac[i * 3] = red(c)
		ac[i * 3 + 1] = green(c)
		ac[i * 3 + 2] = blue(c)

		drawLines()
	}

	colorMode(RGB)
}

function draw() {

	for (let i = 0; i < num; i++) {
		ax[i] += avx[i]
		ay[i] += avy[i]

		if (ax[i] > width) {
			ax[i] = 0
			ay[i] = height/2 + random(-1, 1)
			ad[i] = 0
		}

		stroke(ac[i * 3], ac[i * 3 + 1], ac[i * 3 + 2], 50)

		point(ax[i], ay[i])

		if (ad[i] === 0 && ax[i] > dispersionX) {
			const gd = (ac[i * 3 + 2] / 255) * 0.3

			let rd = (ac[i * 3] / 255) * -0.3
			rd -= gd * rd

			let bd = (ac[i * 3 + 2] / 255) * 0.3
			bd += gd * bd

			avy[i] = rd + bd 
			ad[i] = 1
		}
		if (ad[i] === 1 && ax[i] > dispersionX + dispersionWidth) {
			avy[i] = 0
			ad[i] = 2
		}
	}

	drawLines()
}

